// One output item per mail that matches an open job by sender domain or company name.
// n8n splits the JSON array from /api/jobs into one item per job.
const list = $input.all().map(i => i.json);
const out = [];
for (const m of $('Gmail trigger (recruiter mail)').all()) {
  const mail = m.json;
  const from = String(mail.From || mail.from?.text || mail.from || '').toLowerCase();
  const subject = String(mail.Subject || mail.subject || '');
  const domain = (from.match(/@([a-z0-9.-]+)/) || [])[1] || '';
  const hit = list.find(j => {
    const c = String(j.company || '').toLowerCase();
    const contactDomain = String(j.contact || '').toLowerCase().split('@')[1];
    return (contactDomain && domain === contactDomain) || (c.length > 2 && (from.includes(c) || subject.toLowerCase().includes(c)));
  });
  if (!hit) continue;
  const note = `mail from ${from.replace(/<.*>/, '').trim() || domain}: ${subject}`.slice(0, 300);
  out.push({ json: { job_id: hit.id, note } });
}
return out;
